@pytest.mark.parametrize("motor", ["M0", "M1", "M2"]) def test_evaluator_recomputes_simulator_metrics_from_trace(p1, K, motor): prof = short_profile() lim = config.LIMITS["L-R1"] out, tr = simulate_traced(prof, p1, K, 1.0, lim, config.motor_model(motor)) d_ref = float(prof.stats()["distance_m"]) sim = run_metrics(out, p1, 1.0, d_ref, prof.duration, p1.Ts) tr["v_ref_task_mps"] = tr["v_tracked_mps"] tr["stop_ref_flag"] = np.zeros_like(tr["t_s"]) sim["stop_ok_sim"] = True assert set(CHANNELS) == set(tr) spec = {"battery": dict(V_oc=p1.V_oc, R0=p1.R0_new, Q_Ah=p1.Q_Ah, c_dis=lim.c_dis, c_ch=lim.c_ch, v_min_ratio=lim.v_min_ratio, v_max_ratio=lim.v_max_ratio), "motor": evaluator.motor_spec_from_protocol(motor, frozen.M1_CURVE), "G": p1.G, "r_w": p1.r_w, "Ts_s": p1.Ts, "dt_s": p1.dt, "d_ref_m": d_ref, "rest_intervals": [[0.0, 0.0]]} ev = evaluator.evaluate_trace(tr, spec, config.RULES) cmp = evaluator.compare_with_simulator(ev, sim, config.RULES) > assert cmp["all_ok"], {k: v for k, v in cmp.items() if k != "all_ok" and not v["ok"]} E AssertionError: {'friction_abs_Wh': {'value': 0.0003075180521110443, 'tol': 1e-06, 'ok': False}} E assert False
